$axeAccessor = Get-Content -Raw -LiteralPath (Join-Path $main 'java\dev\aero\cnmterraincompat\mixin\AxeItemAccessor.java')
$canonicalAudit = Get-Content -Raw -LiteralPath (Join-Path $main 'java\dev\aero\cnmterraincompat\CanonicalShapeMapAudit.java')
