$mynxHook = Get-Content -Raw -LiteralPath (Join-Path $main 'java\dev\aero\cnmterraincompat\mixin\MynxTreesInitializationMixin.java')
$ribbitsHook = Get-Content -Raw -LiteralPath (Join-Path $main 'java\dev\aero\cnmterraincompat\mixin\RibbitsInitializationMixin.java')
$bbbHook = Get-Content -Raw -LiteralPath (Join-Path $main 'java\dev\aero\cnmterraincompat\mixin\BbbInitializationMixin.java')
